#!/usr/bin/env bash
set -euo pipefail
SANDBOX="$1"
cd "$SANDBOX"

git init -q -b main
git config user.name "Player"
git config user.email "player@gitmissions.local"
git config commit.gpgsign false

d() { export GIT_AUTHOR_DATE="$1" GIT_COMMITTER_DATE="$1"; }
who() { export GIT_AUTHOR_NAME="$1" GIT_AUTHOR_EMAIL="$1@irrigate.example" GIT_COMMITTER_NAME="$1" GIT_COMMITTER_EMAIL="$1@irrigate.example"; }

cat > requirements.lock <<'EOF'
# generated by pip-compile - do not edit by hand
flask==3.0.0
requests==2.31.0
schedule==1.2.0
EOF
cat > controller.py <<'EOF'
def water_zone(zone, minutes):
    print("watering", zone, "for", minutes, "min")
EOF
who sofia; git add . && d 2025-06-10T08:00:00; git commit -q -m "Garden irrigation controller"

git switch -q -c feature/moisture-alert
who theo
cat > requirements.lock <<'EOF'
# generated by pip-compile - do not edit by hand
flask==3.0.0
requests==2.32.0
schedule==1.2.1
EOF
cat >> controller.py <<'EOF'

def soil_moisture_alert(level):
    return level < 20
EOF
d 2025-06-12T08:00:00; git commit -q -am "Alert when soil moisture drops below 20 percent"

git switch -q main
who sofia
cat > requirements.lock <<'EOF'
# generated by pip-compile - do not edit by hand
flask==3.0.3
requests==2.32.3
schedule==1.2.2
EOF
d 2025-06-13T08:00:00; git commit -q -am "Regenerate lock file from CI (security updates)"
